Algorithm: Scaled Dot-Product Attention (single head)
Input:  X in R^{B x T x d_model}, learned matrices W_Q, W_K, W_V, W_O in R^{d_model x d_model},
        optional mask M in {0, -inf}^{T x T}
Output: Y in R^{B x T x d_model}

  // 1. Project inputs to query, key, value subspaces
  Q := X @ W_Q                                  // shape (B, T, d_k)
  K := X @ W_K                                  // shape (B, T, d_k)
  V := X @ W_V                                  // shape (B, T, d_v)

  // 2. Compute scaled similarity scores
  S := Q @ K^T / sqrt(d_k)                      // shape (B, T, T)

  // 3. Apply causal or padding mask (additive in log-space)
  If M is not None:
      S := S + M                                // -inf at disallowed positions

  // 4. Row-wise softmax produces a probability distribution per query
  A := softmax(S, axis = -1)                    // attention weights, rows sum to 1

  // 5. Weighted sum of values
  Z := A @ V                                    // shape (B, T, d_v)

  // 6. Output projection (identity if d_v = d_model)
  Y := Z @ W_O                                  // shape (B, T, d_model)
  Return Y

from torch import nn
# Position-wise feed-forward network: expand to d_ff, apply ReLU,
# project back to d_model. Applied identically at every sequence position.
class FeedForward(nn.Module):
    def __init__(self, d_model, d_ff, dropout=0.1):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(d_model, d_ff),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(d_ff, d_model),
            nn.Dropout(dropout),
            )
        # Forward pass: define computation graph
    def forward(self, x):
        return self.net(x)

from torch import nn
# GPT-2 style weight initialization: N(0, 0.02) for most layers,
# scaled by 1/sqrt(2*n_layers) for residual projections to stabilize depth.
def init_weights(module, n_layers):
    """GPT-2 style initialization."""
    if isinstance(module, nn.Linear):
        nn.init.normal_(module.weight, mean=0.0, std=0.02)
        if module.bias is not None:
            nn.init.zeros_(module.bias)
        elif isinstance(module, nn.Embedding):
            nn.init.normal_(module.weight, mean=0.0, std=0.02)
            def scale_residual_init(module, n_layers):
                """Scale output projections in residual blocks."""
                for name, param in module.named_parameters():
                    if name.endswith('W_o.weight') or name.endswith('net.3.weight'):
                        # net.3 is the second linear layer in the FFN
                        nn.init.normal_(param, mean=0.0, std=0.02 / (2 * n_layers) ** 0.5)

Algorithm: Decoder-Only Transformer (next-token logits)
Input:  token IDs t in {0,..,V-1}^{B x T}
Output: logits L in R^{B x T x V}

  // 1. Embed + add positional information
  x := Embed[t] * sqrt(d_model)                 // (B, T, d_model)
  x := x + PositionalEncoding(T)                // sinusoidal, learned, or RoPE-applied later

  // 2. Build causal mask
  M[i, j] := 0 if j <= i else -inf              // (T, T)

  // 3. Stack of N Pre-LN blocks
  For l = 1..N:
      h := LayerNorm(x)                         // pre-attention norm
      a := MultiHeadAttention(h, mask = M)      // Algorithm 3.1.1, applied per head
      x := x + a                                // residual

      h := LayerNorm(x)                         // pre-FFN norm
      f := FFN(h)                               // two-layer MLP, often SwiGLU
      x := x + f                                // residual

  // 4. Final norm + unembedding
  x := LayerNorm(x)
  L := x @ E^T                                  // weight-tied with embedding E, shape (B, T, V)
  Return L

import torch
# Define CharDataset; implement __len__, __getitem__, decode
# See inline comments for step-by-step details.
class CharDataset:
    """Character-level dataset that produces (input, target) pairs."""
    def __init__(self, text, block_size):
        self.block_size = block_size
        # Build character vocabulary
        chars = sorted(set(text))
        self.vocab_size = len(chars)
        self.stoi = {ch: i for i, ch in enumerate(chars)}
        self.itos = {i: ch for ch, i in self.stoi.items()}
        # Encode entire text as integers
        self.data = torch.tensor([self.stoi[c] for c in text], dtype=torch.long)
    def __len__(self):
        return len(self.data) - self.block_size
    def __getitem__(self, idx):
        chunk = self.data[idx : idx + self.block_size + 1]
        x = chunk[:-1] # input: characters 0..block_size-1
        y = chunk[1:] # target: characters 1..block_size
        return x, y
    def decode(self, indices):
        """Convert list of integer indices back to string."""
        return ''.join(self.itos[i] for i in indices)
    def encode(self, text):
        """Convert string to list of integer indices."""
        return [self.stoi[c] for c in text]

Algorithm: Sparse Mixture-of-Experts FFN
Input:  token representation x in R^{B x T x d}, E experts {f_1,..,f_E}, top_k = k
Output: y in R^{B x T x d}, plus auxiliary load-balancing loss L_aux

  // 1. Router scores every expert
  g := softmax(x @ W_r)                         // (B, T, E), W_r in R^{d x E}

  // 2. Select top-k experts per token; re-normalize their gates
  (g_top, idx) := topk(g, k, axis = -1)         // each (B, T, k)
  g_top := g_top / sum(g_top, axis = -1, keepdims = True)

  // 3. Dispatch each token to its chosen experts, combine outputs
  y := 0
  For j = 1..k:
      e := idx[..., j]                          // chosen expert index per token
      y := y + g_top[..., j] * f_{e}(x)         // gated expert output

  // 4. Switch Transformer auxiliary loss (Fedus et al., 2021)
  //    f_i = fraction of tokens routed to expert i
  //    p_i = mean gate probability for expert i across the batch
  f := one_hot(idx, E).mean(axis = (B, T, k))   // dispatch fraction per expert
  p := g.mean(axis = (B, T))                    // mean router probability per expert
  L_aux := E * alpha * sum_i (f_i * p_i)        // alpha ~ 0.01

  Return y, L_aux

Why this loss balances? p_i is differentiable in W_r; f_i is not, but in the product f_i * p_i,
gradients pushed by alpha lower p_i precisely for over-used experts, encouraging the router to
spread mass uniformly. A perfectly balanced router yields E * sum_i (1/E)^2 = 1.

Algorithm: Beam Search Decoding
Input:  model M, prompt tokens x, beam width k, max length T, length-norm alpha
Output: highest-scoring complete sequence

  beams := [(x, 0.0)]                     // each beam: (sequence, cumulative log-prob)
  completed := []
  for step in 1..T:
      candidates := []
      for (seq, score) in beams:
          if seq ends with EOS:
              completed.append((seq, score))
              continue
          logits := M.forward(seq)
          log_probs := log_softmax(logits[-1])
          for each token v in vocabulary:
              candidates.append((seq + [v], score + log_probs[v]))
      // Keep only the top k candidates
      beams := top_k(candidates, k, by=score)
      if all beams are completed:
          break
  return argmax(completed, by = score / length^alpha)

