# implement call_with_retry
import time
from openai import OpenAI

client = OpenAI()

def call_with_retry(prompt, max_retries=3, base_delay=1.0):
    """Call the API with exponential backoff on rate limits."""
    for attempt in range(max_retries):
        try:
            response = client.chat.completions.create(
                model="gpt-4o",
                messages=[{"role": "user", "content": prompt}],
                temperature=0.7,
            )
            return response.choices[0].message.content
        except Exception as e:
            if "rate_limit" in str(e).lower() and attempt < max_retries - 1:
                delay = base_delay * (2 ** attempt)
                print(f"Rate limited. Waiting {delay}s...")
                time.sleep(delay)
            else:
                raise

import re
class PIIRedactor:
    """Redact personally identifiable information from text."""
    PATTERNS = {
        "email": r"\b[\w.+-]+@[\w-]+\.[\w.-]+\b",
        "phone": r"\b\d{3}[-.]?\d{3}[-.]?\d{4}\b",
        "ssn": r"\b\d{3}-\d{2}-\d{4}\b",
        "credit_card": r"\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b",
        }
    def redact(self, text: str) -> dict:
        redacted = text
        findings = []
        for pii_type, pattern in self.PATTERNS.items():
            matches = re.findall(pattern, text)
            for match in matches:
                redacted = redacted.replace(match, f"[{pii_type.upper()}_REDACTED]")
                findings.append({"type": pii_type, "value": match[:4] + "***"})
                return {"text": redacted, "findings": findings}
                redactor = PIIRedactor()
                result = redactor.redact("Contact john@example.com or call 555-123-4567")
                print(result["text"])

