from datetime import timedelta
@workflow.defn
class BookingWorkflow:
    """Saga pattern: each step registers a compensation action."""
    @workflow.run
    async def run(self, request: TravelRequest) -> BookingResult:
        compensations: list[tuple[str, dict]] = []
        try:
            # Step 1: Book flight
            flight = await workflow.execute_activity(
                book_flight, request.flight_details,
                start_to_close_timeout=timedelta(seconds=60),
                )
            compensations.append(("cancel_flight", {"id": flight.id}))
            # Step 2: Book hotel
            hotel = await workflow.execute_activity(
                book_hotel, request.hotel_details,
                start_to_close_timeout=timedelta(seconds=60),
                )
            compensations.append(("cancel_hotel", {"id": hotel.id}))
            # Step 3: LLM generates itinerary summary
            itinerary = await workflow.execute_activity(
                generate_itinerary,
                args=[flight, hotel, request.preferences],
                start_to_close_timeout=timedelta(seconds=120),
                )
            return BookingResult(
                flight=flight, hotel=hotel, itinerary=itinerary
                )
        except Exception as e:
            # Execute compensations in reverse order
            for comp_name, comp_args in reversed(compensations):
                await workflow.execute_activity(
                    comp_name, comp_args,
                    start_to_close_timeout=timedelta(seconds=30),
                    )
                raise WorkflowFailedError(f"Booking failed: {e}") from e

from enum import Enum
from dataclasses import dataclass
from datetime import datetime
class FailureCategory(str, Enum):
    # Hard failures
    RATE_LIMIT = "rate_limit"
    TIMEOUT = "timeout"
    SERVER_ERROR = "server_error"
    AUTH_ERROR = "auth_error"
    CONTEXT_OVERFLOW = "context_overflow"
    # Soft failures
    HALLUCINATION = "hallucination"
    REFUSAL = "refusal"
    FORMAT_VIOLATION = "format_violation"
    INSTRUCTION_DRIFT = "instruction_drift"
    QUALITY_DEGRADATION = "quality_degradation"
@dataclass
class FailureEvent:
    category: FailureCategory
    timestamp: datetime
    model: str
    request_id: str
    details: str
    is_hard: bool
    retryable: bool
def classify_failure(status_code: int, response_body: str | None, expected_format: str | None = None) -> FailureEvent | None:
    """Classify an LLM API response into failure categories."""
    now = datetime.now()
    base = {"timestamp": now, "model": "", "request_id": ""}
    # Hard failure classification
    if status_code == 429:
        return FailureEvent(
            category=FailureCategory.RATE_LIMIT,
            details="Rate limit exceeded",
            is_hard=True, retryable=True, **base
            )
        if status_code == 408 or status_code == 504:
            return FailureEvent(
                category=FailureCategory.TIMEOUT,
                details=f"Request timed out (HTTP {status_code})",
                is_hard=True, retryable=True, **base
                )
            if status_code >= 500:
                return FailureEvent(
                    category=FailureCategory.SERVER_ERROR,
                    details=f"Server error (HTTP {status_code})",
                    is_hard=True, retryable=True, **base
                    )
                # Soft failure classification (HTTP 200 but bad content)
                if status_code == 200 and response_body:
                    if expected_format == "json":
                        try:
                            import json
                            json.loads(response_body)
                        except json.JSONDecodeError:
                            return FailureEvent(
                                category=FailureCategory.FORMAT_VIOLATION,
                                details="Expected JSON but received non-JSON response",
                                is_hard=False, retryable=True, **base
                                )
                            refusal_phrases = [
                                "I cannot", "I'm unable to", "I apologize, but I can't",
                                "I'm not able to", "As an AI, I cannot",
                                ]
                            if any(response_body.strip().startswith(p) for p in refusal_phrases):
                                return FailureEvent(
                                    category=FailureCategory.REFUSAL,
                                    details="Model refused the request",
                                    is_hard=False, retryable=True, **base
                                    )
                                return None # No failure detected

