import numpy as np
def tokenize_ts(series, n_bins=256, robust=True):
  x = np.asarray(series)
  if robust:
    lo, hi = np.percentile(x, [1, 99])
  else:
    lo, hi = x.min(), x.max()
  edges = np.linspace(lo, hi, n_bins + 1)
  tokens = np.clip(np.digitize(x, edges) - 1, 0, n_bins - 1)
  return tokens.tolist(), edges

# Process reward model: score each step in a reasoning chain independently.
# Uses per-step scores to identify the weakest link and compute aggregate
# chain reliability as the product of individual step probabilities.
import torch
from dataclasses import dataclass
@dataclass
class ReasoningStep:
    """A single step in a reasoning chain."""
    text: str
    step_index: int
@dataclass
class ReasoningChain:
    """A complete reasoning chain with per-step scores."""
    steps: list[ReasoningStep]
    step_scores: list[float] | None = None
@property
def aggregate_score(self) -> float:
    """Product of step-level scores (probability all steps correct)."""
    if not self.step_scores:
        return 0.0
        score = 1.0
        for s in self.step_scores:
            score *= s
            return score
@property
def min_step_score(self) -> float:
    """Minimum step score (bottleneck step)."""
    if not self.step_scores:
        return 0.0
        return min(self.step_scores)
def select_best_chain(
    chains: list[ReasoningChain],
    strategy: str = "product",
    ) -> ReasoningChain:
"""Select the best reasoning chain using process reward scores.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Strategies:
- "product": chain with highest product of step scores
- "min": chain with highest minimum step score (most reliable)
- "last": chain with highest score on the final step
"""
if strategy == "product":
    return max(chains, key=lambda c: c.aggregate_score)
elif strategy == "min":
        return max(chains, key=lambda c: c.min_step_score)
    elif strategy == "last":
            return max(
                chains,
                key=lambda c: c.step_scores[-1] if c.step_scores else 0.0,
                )
        else:
                raise ValueError(f"Unknown strategy: {strategy}")
                # Example: compare two reasoning chains for "What is 17 * 23?"
                chain_a = ReasoningChain(
                    steps=[
                        ReasoningStep("17 * 23 = 17 * 20 + 17 * 3", 0),
                        ReasoningStep("17 * 20 = 340", 1),
                        ReasoningStep("17 * 3 = 51", 2),
                        ReasoningStep("340 + 51 = 391", 3),
                        ],
                    step_scores=[0.95, 0.98, 0.97, 0.99], # all steps high confidence
                    )
                chain_b = ReasoningChain(
                    steps=[
                        ReasoningStep("17 * 23 = 17 * 25 - 17 * 2", 0),
                        ReasoningStep("17 * 25 = 425", 1),
                        ReasoningStep("17 * 2 = 34", 2),
                        ReasoningStep("425 - 34 = 389", 3), # arithmetic error here
                        ],
                    step_scores=[0.92, 0.96, 0.98, 0.45], # low confidence on last step
                    )
                best = select_best_chain([chain_a, chain_b], strategy="product")
                print(f"Selected chain score: {best.aggregate_score:.4f}")
                # chain_a wins: 0.95*0.98*0.97*0.99 = 0.8935 vs 0.92*0.96*0.98*0.45 = 0.3893

Algorithm: Total-cost-optimal (N*, D*) accounting for inference
Input:  expected lifetime inference tokens T_inf
        Chinchilla parameters (E, A, B, alpha, beta) from Algorithm 6.3.1
        FLOPs constants: train = 6 N D, inference = 2 N per generated token
Output: (N*, D*) minimizing total FLOPs cost for target loss L_target

  // 1. Total compute = training + inference
  C_total(N, D) := 6 N D + 2 N T_inf

  // 2. Substitute D from the loss constraint L(N, D) = L_target
  //    using L(N, D) = E + A / N^alpha + B / D^beta
  D(N) := ( B / (L_target - E - A / N^alpha) )^{1 / beta}

  // 3. Minimize C_total(N, D(N)) over N
  Solve dC_total / dN = 0 numerically (one-dimensional convex problem)

  // 4. Interpretation: the optimum trades 6 D training FLOPs against 2 T_inf
  //    inference FLOPs per parameter. As T_inf grows, the optimum N* shrinks
  //    (smaller model) and D* grows (more training tokens per parameter).

  Return (N*, D*)

Practical regime (T_inf >> training tokens):
    N* ~= 0.3 to 0.5 * N*_Chinchilla   (smaller model)
    D* ~= 5 to 20 * D*_Chinchilla     (over-train on more data)
    matches Llama-3 8B (15T tokens, ~1875 tokens/param, ~94x Chinchilla)

# MinHash + LSH deduplication: hash character n-grams into signatures,
# bucket similar documents together, and flag near-duplicate pairs.
import hashlib
from collections import defaultdict
def get_ngrams(text, n=5):
    """Extract character n-grams from text."""
    words = text.lower().split()
    return set(
        " ".join(words[i:i+n])
        for i in range(len(words) - n + 1)
        )
def minhash_signature(ngrams, num_hashes=128):
    """Compute MinHash signature for a set of n-grams."""
    signature = []
    for i in range(num_hashes):
        min_hash = float('inf')
        for ngram in ngrams:
            # Hash with a different seed for each hash function
            h = int(hashlib.sha256(
                f"{i}:{ngram}".encode()
                ).hexdigest(), 16)
            min_hash = min(min_hash, h)
            signature.append(min_hash)
            return signature
def lsh_buckets(signature, bands=16):
    """Split signature into bands for LSH bucketing."""
    rows_per_band = len(signature) // bands
    buckets = []
    for b in range(bands):
        start = b * rows_per_band
        band_hash = hash(tuple(signature[start:start + rows_per_band]))
        buckets.append((b, band_hash))
        return buckets
# Example: find near-duplicates
docs = [
    "The quick brown fox jumps over the lazy dog in the park",
    "The quick brown fox jumps over a lazy dog in the park", # near-dup
    "Machine learning models require large amounts of data",
    ]
bucket_index = defaultdict(list)
for doc_id, doc in enumerate(docs):
    ngrams = get_ngrams(doc, n=3)
    sig = minhash_signature(ngrams, num_hashes=64)
    for bucket in lsh_buckets(sig, bands=8):
        bucket_index[bucket].append(doc_id)
        # Find candidate pairs that share a bucket
        candidates = set()
        for docs_in_bucket in bucket_index.values():
            if len(docs_in_bucket) > 1:
                for i in range(len(docs_in_bucket)):
                    for j in range(i+1, len(docs_in_bucket)):
                        candidates.add((docs_in_bucket[i], docs_in_bucket[j]))
                        print(f"Near-duplicate candidates: {candidates}")

# Minimal quality filtering pipeline
import re
from collections import Counter
def heuristic_quality_filter(doc: str) -> dict:
    """Apply heuristic quality filters to a document."""
    words = doc.split()
    lines = doc.strip().split("\n")
    chars = len(doc)
    word_count = len(words)
    # Length check
    if word_count < 50:
        return {"pass": False, "reason": "too_short"}
        # Alphabetic character ratio
        alpha_ratio = sum(c.isalpha() for c in doc) / max(chars, 1)
        if alpha_ratio < 0.6:
            return {"pass": False, "reason": "low_alpha"}
            # Repeated line ratio (boilerplate detection)
            line_counts = Counter(lines)
            repeated = sum(c - 1 for c in line_counts.values() if c > 1)
            if repeated / max(len(lines), 1) > 0.3:
                return {"pass": False, "reason": "repetitive"}
                # URL density (spam detection)
                url_count = len(re.findall(r"https?://", doc))
                if url_count / max(word_count, 1) > 0.1:
                    return {"pass": False, "reason": "url_heavy"}
                    return {"pass": True, "words": word_count, "alpha": round(alpha_ratio, 3)}
                    # Test on sample documents
                    samples = [
                        ("Good article", "The transformer architecture has revolutionized NLP by enabling parallel attention. " * 8),
                        ("Too short", "Click here now"),
                        ("Spam", "Visit https://a.com and https://b.com and https://c.com now " * 5),
                        ("Repetitive", ("Buy now!\n" * 20) + "Some padding text to reach minimum length for a valid document check."),
                        ]
                    for label, doc in samples:
                        result = heuristic_quality_filter(doc)
                        print(f"{label:>15}: {result}")

import math
WARM, TOTAL, MIN = 2000, 100_000, 0.1
def lr_lambda(step):
  if step < WARM: return step / WARM
  p = (step - WARM) / (TOTAL - WARM)
  return MIN + (1 - MIN) * 0.5 * (1 + math.cos(math.pi * p))

import torch.distributed.checkpoint as dcp
from torch.distributed.checkpoint.state_dict import (
    get_model_state_dict,
    get_optimizer_state_dict,
    set_model_state_dict,
    set_optimizer_state_dict,
    StateDictOptions,
)
# --- Saving a sharded checkpoint ---
def save_checkpoint(model, optimizer, step, checkpoint_dir):
    """Save a reshardable distributed checkpoint."""
    state_dict = {
        "model": get_model_state_dict(model),
        "optimizer": get_optimizer_state_dict(model, optimizer),
        "step": step,
    }
    dcp.save(
        state_dict=state_dict,
        storage_writer=dcp.FileSystemWriter(
        f"{checkpoint_dir}/step_{step}",
        single_file_per_rank=True, # One file per rank for parallel I/O
        ),
    )
# --- Loading with potentially different parallelism ---
def load_checkpoint(model, optimizer, checkpoint_dir, step):
    """Load checkpoint; DCP handles resharding automatically."""
    state_dict = {
        "model": get_model_state_dict(model),
        "optimizer": get_optimizer_state_dict(model, optimizer),
    }
    dcp.load(
        state_dict=state_dict,
        storage_reader=dcp.FileSystemReader(
        f"{checkpoint_dir}/step_{step}"
        ),
    )
    # Apply loaded state back to model and optimizer
    set_model_state_dict(
        model, state_dict["model"],
        options=StateDictOptions(strict=True),
    )
    set_optimizer_state_dict(
        model, optimizer, state_dict["optimizer"],
    )
    return state_dict.get("step", 0)

