def git_describe_dirty() -> str:
    """Return e.g. 'v1.0.2-3-gabc123' or 'abc123-dirty' if uncommitted edits exist."""
    return subprocess.check_output(
        ["git", "describe", "--always", "--dirty", "--tags"],
