# A retrieval tool exposed to an agent via the function-calling interface.
# The agent picks `query`, `corpus`, and optional filters; the wrapper
# handles vector search, formatting, and error surfaces.
from typing import Literal, Optional
from pydantic import BaseModel, Field

class SearchDocsArgs(BaseModel):
    query: str = Field(..., description="A natural-language search query.")
    corpus: Literal["product_docs", "runbooks", "slack_archive"] = Field(
        description="Which knowledge base to search."
    )
    since: Optional[str] = Field(None, description="ISO date filter (YYYY-MM-DD).")
    k: int = Field(5, ge=1, le=20, description="Number of passages to return.")

def search_docs(args: SearchDocsArgs) -> dict:
    """Vector-search a named corpus and return structured passages.

    Returns a stable JSON shape: a list of passages with source_id,
    score, and excerpt, plus a `status` the agent can branch on.
    """
    hits = retriever.search(
        corpus=args.corpus,
        query=args.query,
        k=args.k,
        filter={"date_gte": args.since} if args.since else None,
    )
    if not hits:
        return {"status": "no_results", "passages": [],
                "hint": "Try a different corpus or broader query."}
    return {
        "status": "ok",
        "passages": [{"source_id": h.id,
                      "score": round(h.score, 3),
                      "excerpt": h.text[:800]}
                     for h in hits],
    }

# Full solution for the framework-selection lab.
# Uses an LLM judge to score each candidate on the task description.
from openai import OpenAI
from pathlib import Path

client = OpenAI()

FRAMEWORKS = {
    "LangGraph": "Strong for explicit graph-based control flow; good with cycles and conditional edges; native LangChain integration.",
    "AutoGen":   "Optimized for conversational multi-agent systems; group chat patterns; human-in-the-loop friendly.",
    "CrewAI":    "Role-based agents (manager, researcher, writer); sequential or hierarchical processes; simple API.",
    "Swarm":     "Minimal, stateless agent routing primitives; good for tool-handoff patterns; easy to inspect.",
}

JUDGE_PROMPT = """Rate how well the framework below fits the task on a 0-10 scale.
Return ONLY a number between 0 and 10.

Framework: {name}
Description: {desc}

Task: {task}

Score:"""

def load_task_description() -> str:
    p = Path("prompt.txt")
    if p.exists(): return p.read_text(encoding="utf-8")
    return "Build a 3-agent pipeline for researching, drafting, and editing news articles."

def score_framework(name: str, task: str) -> float:
    resp = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": JUDGE_PROMPT.format(name=name, desc=FRAMEWORKS[name], task=task)}],
        temperature=0.0,
        max_tokens=4,
    )
    try:
        return float(resp.choices[0].message.content.strip()) / 10.0
    except ValueError:
        return 0.5

if __name__ == "__main__":
    task = load_task_description()
    scored = sorted(((n, score_framework(n, task)) for n in FRAMEWORKS), key=lambda x: -x[1])
    print(f"Task: {task!r}\n")
    for name, fit in scored:
