# Two chunking primitives: fixed-window-with-overlap and heading-aware.
# tiktoken gives us exact token counts so chunks fit a known embedding budget.
import tiktoken

def chunk_by_tokens(text: str, max_tokens: int = 512, overlap: int = 50) -> list[dict]:
    """Sliding-window chunking with token-level overlap to avoid splitting facts."""
    encoder = tiktoken.encoding_for_model("gpt-4o")
    tokens = encoder.encode(text)
    chunks = []
    start = 0
    while start < len(tokens):
        end = start + max_tokens
        window = tokens[start:end]
        chunks.append({
            "text": encoder.decode(window),
            "token_count": len(window),
            "start_token": start,
        })
        start = end - overlap  # slide window, keep `overlap` tokens of context
    return chunks

def chunk_by_structure(markdown_text: str) -> list[dict]:
    """Split a markdown doc on heading boundaries; each section becomes one chunk."""
    sections, current = [], {"heading": "", "content": []}
    for line in markdown_text.split("\n"):
        if line.startswith("#"):
            # A new heading closes the previous section.
            if current["content"]:
                sections.append(current)
            current = {"heading": line.lstrip("# "), "content": []}
        else:
            current["content"].append(line)
    if current["content"]:  # flush the trailing section
        sections.append(current)
    return [
        {"text": "\n".join(s["content"]), "metadata": {"heading": s["heading"]}}
        for s in sections
    ]

# Self-correcting SQL loop: when the generated query throws, feed the error back
# to the LLM and ask for a fix. Bounded retries keep one bad query from looping forever.
import sqlite3
def execute_with_retry(question, schema_context, db_path,
    max_retries=3):
    """Execute SQL with automatic error correction."""
    conn = sqlite3.connect(db_path)
    error_history = []
    for attempt in range(max_retries):
        # Generate SQL (include errors from prior attempts)
        if error_history:
            error_context = "\n".join([
                f"Attempt {e['attempt']}: {e['sql']}\n"
                f"Error: {e['error']}"
                for e in error_history
                ])
            question_with_context = (
                f"{question}\n\nPrevious failed attempts:\n"
                f"{error_context}\n\nFix the errors."
                )
        else:
            question_with_context = question
            sql = text_to_sql(question_with_context, schema_context)
            try:
                cursor = conn.execute(sql)
                columns = [desc[0] for desc in cursor.description]
                rows = cursor.fetchall()
                return {
                    "sql": sql,
                    "columns": columns,
                    "rows": rows,
                    "attempts": attempt + 1
                    }
            except Exception as e:
                error_history.append({
                    "attempt": attempt + 1,
                    "sql": sql,
                    "error": str(e)
                    })
                return {"error": "Failed after max retries",
                    "history": error_history}

