# Minimal observability wrapper for either realtime API.
# Logs every event with monotonic-clock timestamps to a JSONL file.
import time, json

class EventLogger:
    def __init__(self, path):
        self.f = open(path, "a")
        self.t0 = time.monotonic()

    def log(self, direction, event):
        elapsed_ms = (time.monotonic() - self.t0) * 1000
        self.f.write(json.dumps({
            "t_ms": round(elapsed_ms, 1),
            "dir": direction,
            "type": event.get("type") or type(event).__name__,
            "summary": str(event)[:200],
        }) + "\n")
        self.f.flush()

import base64
from openai import OpenAI
client = OpenAI()
def encode_image_to_base64(image_path: str) -> str:
    """Read an image file and encode it as base64."""
    with open(image_path, "rb") as f:
        return base64.b64encode(f.read()).decode("utf-8")
class MultimodalConversation:
    """Conversational AI with vision capabilities."""
    def __init__(self, system_prompt: str):
        self.system_prompt = system_prompt
        self.history: list[dict] = []
    def send_text(self, user_message: str) -> str:
        """Send a text-only message."""
        self.history.append({
            "role": "user",
            "content": user_message
            })
        return self._get_response()
    def send_image(self, image_path: str,
        question: str = "What do you see?") -> str:
        """Send an image with an optional question."""
        b64_image = encode_image_to_base64(image_path)
        # Determine MIME type from extension
        ext = image_path.rsplit(".", 1)[-1].lower()
        mime_map = {"jpg": "jpeg", "jpeg": "jpeg",
            "png": "png", "gif": "gif", "webp": "webp"}
        mime_type = f"image/{mime_map.get(ext, 'jpeg')}"
        self.history.append({
            "role": "user",
            "content": [
            {"type": "text", "text": question},
            {
            "type": "image_url",
            "image_url": {
            "url": f"data:{mime_type};base64,{b64_image}",
            "detail": "high"
            }
            }
            ]
            })
        return self._get_response()
    def send_image_url(self, url: str, question: str) -> str:
        """Send an image via URL with a question."""
        self.history.append({
            "role": "user",
            "content": [
            {"type": "text", "text": question},
            {
            "type": "image_url",
            "image_url": {"url": url, "detail": "auto"}
            }
            ]
            })
        return self._get_response()
    def _get_response(self) -> str:
        """Get a response from the multimodal LLM."""
        messages = [
            {"role": "system", "content": self.system_prompt},
            *self.history
            ]
        response = client.chat.completions.create(
            model="gpt-4o",
            messages=messages,
            max_tokens=1000
            )
        assistant_msg = response.choices[0].message.content
        self.history.append({
            "role": "assistant", "content": assistant_msg
            })
        return assistant_msg
